UPDATE chat_rooms
SET status = 'ENDED', ended_at = #{endedAt}, active_pair_key = NULL
WHERE id = #{id}

mapper.select:
SELECT * FROM chat_messages
WHERE room_id = #{roomId}
AND created_at < #{beforeCreatedAt}
ORDER BY created_at DESC
LIMIT #{limit}

